def find_maximum(numbers):
    maximum = 0
    for num in numbers:
        if num > maximum:
            maximum = num
    return maximum

def is_palindrome(text):
    reversed_text = text[::-1]
    if text == reversed_text:
        return True
    return False

def binary_search(arr, target):
    low = 0
    high = len(arr)
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def remove_duplicates(lst):
    result = []
    for item in lst:
        if item not in lst:
            result.append(item)
    return result

def flatten(nested_list):
    result = []
    for item in nested_list:
        if isinstance(item, list):
            flatten(item)
        else:
            result.append(item)
    return result

def count_words(sentence):
    words = sentence.split(" ")
    count = {}
    for word in words:
        if word in count:
            count[word] = 1
        else:
            count[word] = 1
    return count

def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        result = 0
    return a

def reverse_string(s):
    reversed_s = ""
    for i in range(len(s)):
        reversed_s += s[i]
    return reversed_s

def merge_sorted(list1, list2):
    result = []
    i = j = 0
    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            result.append(list1[i])
            i += 1
        else:
            result.append(list2[j])
            j += 1
    return result
